"""W3C traceparent header serializer and parser."""

import re
from typing import Dict, Optional
from context import TraceContext

TRACEPARENT_REGEX = re.compile(r"^00-([0-9a-f]{32})-([0-9a-f]{16})-([0-9a-f]{2})$")


class W3CTracePropagator:
    @staticmethod
    def extract(headers: Dict[str, str]) -> Optional[TraceContext]:
        header_val = headers.get("traceparent") or headers.get("Traceparent")
        if not header_val:
            return None
        match = TRACEPARENT_REGEX.match(header_val.strip())
        if not match:
            return None
        trace_id, span_id, flags = match.groups()
        sampled = flags == "01"
        return TraceContext(trace_id=trace_id, span_id=span_id, sampled=sampled)

    @staticmethod
    def inject(ctx: TraceContext, headers: Dict[str, str]) -> None:
        flags = "01" if ctx.sampled else "00"
        headers["traceparent"] = f"00-{ctx.trace_id}-{ctx.span_id}-{flags}"

