"""Tracer generating spans and maintaining active scopes."""

import uuid
from typing import Optional
from context import TraceContext
from span import Span


def generate_id(length: int) -> str:
    return uuid.uuid4().hex[:length]


class Tracer:
    def start_span(self, name: str, parent_ctx: Optional[TraceContext] = None) -> Span:
        new_span_id = generate_id(16)
        if parent_ctx:
            # Inherit trace_id and set parent_span_id
            ctx = TraceContext(
                trace_id=parent_ctx.trace_id,
                span_id=new_span_id,
                parent_span_id=parent_ctx.span_id,
                sampled=parent_ctx.sampled,
            )
        else:
            ctx = TraceContext(
                trace_id=generate_id(32),
                span_id=new_span_id,
                parent_span_id=None,
                sampled=True,
            )
        return Span(name=name, context=ctx)
